async function trainedModelPage(){
 main.innerHTML=intro('','Trained model','Predict sales using a saved linear regression model trained in Python with scikit-learn stochastic gradient descent.')+'<p role="status">Loading trained model…</p>';
 try{
 const response=await fetch('models/sales-sgd.json');if(!response.ok)throw Error('Model could not be loaded.');const m=await response.json();
 if(location.hash!=='#trained-model')return;
 const metricRows=[['SGD regression',m.metrics.test],['Least-squares reference',m.metrics.least_squares],['Training-mean baseline',m.metrics.baseline]];
 main.innerHTML=intro('','Trained model','Predict sales using a saved linear regression model trained in Python with scikit-learn stochastic gradient descent.')+`
 <section class="card"><h2 style="margin-top:0">Sales prediction</h2><p>Enter advertising spend in thousands of dollars. Output sales is in thousands of units, following the dataset convention.</p>
 <form id="predict-form"><div class="prediction-inputs">${m.features.map((f,i)=>`<div><label for="feature-${i}">${f} spend</label><input id="feature-${i}" type="number" min="0" max="1000000" step="any" value="${m.test_examples[0].inputs[i]}" required><small>Training range: ${m.ranges[i].min}–${m.ranges[i].max}</small></div>`).join('')}</div><button style="margin-top:16px">Predict sales</button></form><div id="prediction" role="status" class="notice"></div><button id="example" class="secondary">Load next held-out example</button></section>
 <h2>Evaluation on unseen rows</h2><p>The model trained on ${m.train_rows} observations; ${m.test_rows} observations were reserved for testing. The split uses seed ${m.seed}. Scaling was fitted only on training rows.</p>
 <div class="scroll"><table><thead><tr><th>Model</th><th>Test RMSE</th><th>Test MAE</th><th>Test R²</th></tr></thead><tbody>${metricRows.map(([name,v])=>`<tr><td>${name}</td><td>${v.rmse.toFixed(3)}</td><td>${v.mae.toFixed(3)}</td><td>${v.r2.toFixed(3)}</td></tr>`).join('')}</tbody></table></div><p class="notice">RMSE and MAE are in thousands of sales units; lower is better. R² compares explained variance with a constant predictor; higher is better. This is one fixed test split, not a guarantee of future accuracy.</p>
 <h2>Actual versus predicted sales</h2><svg viewBox="0 0 600 300" role="img" aria-label="Held-out actual versus predicted sales scatter plot" style="width:100%;background:white;border:1px solid var(--border)"><path d="M55 20V250H565" fill="none" stroke="#555"/><path d="M55 250L565 20" stroke="#aaa" stroke-dasharray="4 4"/>${[0,10,20,30].map(v=>`<text x="${55+v/30*510}" y="270" font-size="12" text-anchor="middle">${v}</text><text x="45" y="${254-v/30*230}" font-size="12" text-anchor="end">${v}</text>`).join('')}${m.test_examples.map(e=>`<circle cx="${55+e.actual/30*510}" cy="${250-e.prediction/30*230}" r="3" fill="var(--accent)"><title>Actual ${e.actual.toFixed(2)}, predicted ${e.prediction.toFixed(2)}</title></circle>`).join('')}<text x="280" y="294" font-size="12">Actual sales</text><text x="17" y="150" transform="rotate(-90 17 150)" font-size="12">Predicted sales</text></svg><p style="font-size:12px">Each point is one held-out row. Dashed diagonal: perfect predictions.</p>
 <h2>How this model was trained</h2><ol><li>Load the Kaggle Advertising CSV; use TV, Radio and Newspaper to predict Sales.</li><li>Reserve 20% of rows before fitting anything.</li><li>Standardize the three features with training-set means and standard deviations.</li><li>Fit SGDRegressor with squared-error loss, no regularization, and a constant learning rate of 0.01. Training completed after ${m.epochs} epochs.</li><li>Export learned coefficients and scaling parameters to JSON. The browser applies these exact parameters to new inputs.</li></ol>
 <div class="formula">ŷ = ${m.intercept.toFixed(4)} ${m.coefficients.map((c,i)=>`${c>=0?'+':'−'} ${Math.abs(c).toFixed(4)} z<sub>${i+1}</sub>`).join(' ')}<br><small>z = (input − training mean) / training standard deviation</small></div><p>This model uses three inputs and stochastic updates. The original Demo uses one input and full-batch gradient descent, allowing you to compare two optimization settings.</p><p><a href="models/sales-sgd.json" download>Download model and evaluation report</a> · <a href="#demo">Open gradient descent demo</a></p>`;
 let idx=0,showActual=true;
 const predict=()=>{const values=m.features.map((_,i)=>Number(document.querySelector('#feature-'+i).value));if(values.some(v=>!Number.isFinite(v)||v<0||v>1000000))return;const prediction=m.intercept+values.reduce((s,v,i)=>s+m.coefficients[i]*(v-m.mean[i])/m.scale[i],0);const outside=values.some((v,i)=>v<m.ranges[i].min||v>m.ranges[i].max);document.querySelector('#prediction').textContent=`Predicted sales: ${prediction.toFixed(3)} thousand units.`+(showActual?` Held-out row ${m.test_examples[idx].row}: actual sales ${m.test_examples[idx].actual.toFixed(3)} thousand units.`:'')+(outside?' At least one input is outside the training range; this is extrapolation.':'')+(prediction<0?' Negative output is a limitation of unconstrained linear regression.':'');};
 document.querySelector('#predict-form').onsubmit=e=>{e.preventDefault();predict()};m.features.forEach((_,i)=>document.querySelector('#feature-'+i).oninput=()=>{showActual=false;document.querySelector('#prediction').textContent='Inputs changed. Select Predict sales to update the result.'});document.querySelector('#example').onclick=()=>{idx=(idx+1)%m.test_examples.length;m.features.forEach((_,i)=>document.querySelector('#feature-'+i).value=m.test_examples[idx].inputs[i]);showActual=true;predict()};predict();
 }catch(e){if(location.hash==='#trained-model')main.innerHTML=intro('','Trained model',e.message)}
}
